using System;using System.Linq;using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;using Unity.AI.Navigation;using TMPro;using FireSafety;
public static class PolishSchoolExterior {
static Transform root;static Material wall,metal;
static void Box(string n,Vector3 p,Vector3 s,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(root,false);g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=m;}
public static object Run(){AssetDatabase.Refresh();root=new GameObject("School exterior finishing").transform;root.SetParent(GameObject.Find("School expansion").transform,false);var mats=UnityEngine.Object.FindObjectsByType<Renderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m).ToArray();wall=mats.First(m=>m.name=="Classroom_PaintedPlasterWall");metal=mats.First(m=>m.name=="Exit - anodized dark metal");Box("Continuous corridor roof",new Vector3(4.9f,3.07f,-.15f),new Vector3(3.5f,.18f,43.4f),wall);Box("Exterior fascia",new Vector3(6.69f,3.18f,-.15f),new Vector3(.12f,.3f,43.4f),wall);Box("Roof edge flashing",new Vector3(6.77f,3.34f,-.15f),new Vector3(.2f,.04f,43.4f),metal);
foreach(float z in new[]{-21.4f,-12.83f,-4.275f,4.275f,12.83f,21.1f})Box("Facade pier",new Vector3(6.57f,1.55f,z),new Vector3(.3f,3.1f,.34f),wall);
Box("Central exit canopy",new Vector3(7.4f,2.96f,-.2f),new Vector3(1.7f,.13f,3.8f),metal);
var soil=AssetDatabase.LoadAssetAtPath<Material>("Assets/_FireSafety/SchoolExpansion/Materials/Garden soil.mat");soil.color=Color.white;soil.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/ThirdParty/SchoolExpansion/leafy_grass/leafy_grass_diff_1k.jpg"));soil.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/ThirdParty/SchoolExpansion/leafy_grass/leafy_grass_nor_gl_1k.png"));soil.EnableKeyword("_NORMALMAP");soil.SetTextureScale("_BaseMap",new Vector2(2,3));soil.SetFloat("_Smoothness",.05f);EditorUtility.SetDirty(soil);
var student=UnityEngine.Object.FindAnyObjectByType<SchoolEvacuationController>().people[3];NavMeshHit hit;if(NavMesh.SamplePosition(new Vector3(.1f,0,3.35f),out hit,.2f,NavMesh.AllAreas)){student.initialPosition=hit.position;student.transform.position=hit.position;}
var surface=UnityEngine.Object.FindAnyObjectByType<NavMeshSurface>();surface.BuildNavMesh();var generated=surface.navMeshData;var saved=AssetDatabase.LoadAssetAtPath<NavMeshData>("Assets/_FireSafety/SchoolExpansion/Navigation/SchoolNavMesh.asset");EditorUtility.CopySerialized(generated,saved);surface.RemoveData();surface.navMeshData=saved;surface.AddData();UnityEngine.Object.DestroyImmediate(generated);EditorUtility.SetDirty(saved);EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();return "Courtyard planting surface and continuous school roofline finished";}}

